            "Quran 9:129": ["ar": "القرآن ٩:١٢٩", "ur": "قرآن 9:129", "fr": "Coran 9:129", "zh-Hans": "古兰经 9:129", "de": "Koran 9:129", "hi": "क़ुरआन 9:129", "tr": "Kur'an 9:129", "ru": "Коран 9:129"],
            "Quran 20:114": ["ar": "القرآن ٢٠:١١٤", "ur": "Quran 20:114", "fr": "Quran 20:114", "zh-Hans": "Quran 20:114", "de": "Quran 20:114", "hi": "Quran 20:114", "tr": "Quran 20:114", "ru": "Quran 20:114"],
            
            // MARK: - Dua Translations
            "In the Name of Allah with Whose Name there is protection against every kind of harm in the earth or in the heaven, and He is the All-Hearing and All-Knowing.": [
                "ar": "",
                "ur": "اللہ کے نام سے، جس کے نام کے ساتھ زمین و آسمان کی کوئی چیز نقصان نہیں پہنچا سکتی، اور وہ سب کچھ سننے والا، جاننے والا ہے۔",
                "fr": "Au nom d'Allah, avec le nom duquel rien sur terre ni au ciel ne peut nuire, et Il est l'Audient, l'Omniscient.",
                "zh-Hans": "奉安拉之名，借祂的名，天地间没有任何事物能造成伤害，祂是全聪的，全知的。",
                "de": "Im Namen Allahs, mit dessen Namen nichts auf der Erde noch im Himmel schaden kann, und Er ist der Allhörende, der Allwissende.",
                "hi": "अल्लाह के नाम से, जिसके नाम के साथ पृथ्वी या आकाश में कोई भी चीज़ नुकसान नहीं पहुँचा सकती, और वह सब कुछ सुनने वाला, सब कुछ जानने वाला है।",
                "tr": "İsmi sayesinde yerde ve gökte hiçbir şeyin zarar veremeyeceği Allah'ın adıyla. O her şeyi işitendir, bilendir.",
                "ru": "С именем Аллаха, с именем Которого ничто не причинит вреда ни на земле, ни на небесах, ведь Он — Слышащий, Знающий."
            ],
            "I am pleased with Allah as my Lord, with Islam as my religion and with Muhammad (peace and blessings be upon him) as my Prophet.": [
                "ar": "",
                "ur": "میں اللہ کے رب ہونے، اسلام کے دین ہونے اور محمد (صلی اللہ علیہ وسلم) کے نبی ہونے پر راضی ہوں۔",
                "fr": "J'accepte Allah comme mon Seigneur, l'Islam comme ma religion et Muhammad (paix et bénédictions sur lui) comme mon Prophète.",
                "zh-Hans": "我满意安拉为我的主，伊斯兰为我的宗教，穆罕默德（愿主福安之）为我的先知。",
                "de": "Ich bin zufrieden mit Allah als meinem Herrn, mit dem Islam als meiner Religion und mit Muhammad (Friede und Segen seien auf ihm) als meinem Propheten.",
                "hi": "मैं अल्लाह को अपना रब, इस्लाम को अपना धर्म और मुहम्मद (उन पर शांति और आशीर्वाद हो) को अपना पैगंबर मानकर प्रसन्न हूं।",
                "tr": "Rab olarak Allah'tan, din olarak İslam'dan ve peygamber olarak Muhammed'den (s.a.v) razı oldum.",
                "ru": "Я доволен Аллахом как Господом, исламом как религией и Мухаммадом (мир ему и благословение) как Пророком."
            ],
            "I ask Allah for forgiveness (three times).": [
                "ar": "",
                "ur": "میں اللہ سے بخشش مانگتا ہوں (تین بار)۔",
                "fr": "Je demande pardon à Allah (trois fois).",
                "zh-Hans": "我祈求安拉的宽恕（三次）。",
                "de": "Ich bitte Allah um Vergebung (dreimal).",
                "hi": "मैं अल्लाह से क्षमा मांगता हूं (तीन बार)।",
                "tr": "Allah'tan bağışlanma dilerim (üç kez).",
                "ru": "Я прошу прощения у Аллаха (три раза)."
            ],
            "O Allah, You are Peace and from You comes peace. Blessed are You, O Owner of majesty and honor.": [
                "ar": "",
                "ur": "اے اللہ! تو سلامتی والا ہے اور تیری طرف سے سلامتی ہے۔ اے جلال و اکرام والے، تو بڑی برکتوں والا ہے۔",
                "fr": "Ô Allah, Tu es la Paix et de Toi vient la paix. Béni sois-Tu, Ô Détenteur de la majesté et de la noblesse.",
                "zh-Hans": "主啊！您是和平的，和平源自您。愿您充满吉庆，威严与尊贵的主啊。",
                "de": "O Allah, Du bist der Frieden und von Dir kommt der Frieden. Segensreich bist Du, O Besitzer von Majestät und Ehre.",
                "hi": "हे अल्लाह, आप शांति हैं और शांति आपकी ओर से आती है। हे महिमा और सम्मान के स्वामी, आप धन्य हैं।",
                "tr": "Ey Allah'ım! Sen selamsın, selamet sendendir. Ey celal ve ikram sahibi, sen yücesin.",
                "ru": "О Аллах, Ты — Мир, и от Тебя — мир. Благословен Ты, Обладатель величия и почета."
            ],
            "O Allah, I seek refuge in You from anxiety and sorrow, weakness and laziness, miserliness and cowardice, the burden of debts and from being overpowered by men.": [
                "ar": "",
                "ur": "اے اللہ! میں تیری پناہ مانگتا ہوں فکر اور غم سے، عاجزی اور سستی سے، کنجوسی اور بزدلی سے، قرض کے بوجھ اور لوگوں کے غلبے سے۔",
                "fr": "Ô Allah, je cherche refuge auprès de Toi contre l'anxiété et le chagrin, la faiblesse et la paresse, l'avarice et la lâcheté, le fardeau des dettes et la domination des hommes.",
                "zh-Hans": "主啊！我求庇于您，免遭忧虑与悲伤、软弱与懒惰、吝啬与怯懦、债务重压及受人欺压。",
                "de": "O Allah, ich suche Zuflucht bei Dir vor Sorge und Traurigkeit, Schwäche und Faulheit, Geiz und Feigheit, der Last von Schulden und davor, von Männern überwältigt zu werden.",
                "hi": "हे अल्लाह, मैं चिंता और दुख, कमजोरी और आलस्य, कंजूसी और कायरता, कर्ज के बोझ और लोगों के दबदबे से आपकी शरण मांगता हूं।",
                "tr": "Ey Allah'ım! Üzüntüden ve kederden, acizlikten ve tembellikten, cimrilikten ve korkaklıktan, borç altında ezilmekten ve insanların kahrından sana sığınırım.",
                "ru": "О Аллах, я прибегаю к Тебе от тревоги и печали, от слабости и лени, от скупости и трусости, от бремени долгов и от притеснения людей."
            ],
            "There is no deity except You; exalted are You. Indeed, I have been of the wrongdoers.": [
                "ar": "",
                "ur": "تیرے سوا کوئی معبود نہیں، تو پاک ہے۔ بیشک میں ہی ظالموں میں سے تھا۔",
                "fr": "Il n'y a de divinité que Toi; Exalté sois-Tu. J'ai été vraiment du nombre des injustes.",
                "zh-Hans": "万物非主，唯有您；赞美您超绝万物。我确是行亏的。",
                "de": "Es gibt keinen Gott außer Dir; gepriesen seist Du. Wahrlich, ich gehörte zu den Ungerechten.",
                "hi": "आपके सिवा कोई पूज्य नहीं; आप महान हैं। वास्तव में, मैं ही गलत करने वालों में से रहा हूं।",
                "tr": "Senden başka ilah yoktur; sen yücesin. Gerçekten ben zalimlerden oldum.",
                "ru": "Нет божества, кроме Тебя; пречист Ты. Поистине, я был из числа несправедливых."
            ],
            "Glory be to Him who has subjected this to us, and we could not have otherwise subdued it. And indeed we, to our Lord, will [surely] return.": [
                "ar": "",
                "ur": "پاک ہے وہ ذات جس نے اسے ہمارے تابع کر دیا، ورنہ ہم اسے قابو کرنے کی طاقت نہیں رکھتے تھے۔ اور یقیناً ہم اپنے رب کی طرف لوٹنے والے ہیں۔",
                "fr": "Gloire à Celui qui a soumis cela pour nous, alors que nous n'étions pas capables de le dominer. Et c'est vers notre Seigneur que nous retournerons.",
                "zh-Hans": "赞美安拉，他为我们制服了这交通工具，否则我们无法控制它。我们必定要归于我们的主。",
                "de": "Preis sei Ihm, der uns dies dienstbar gemacht hat, und wir hätten es sonst nicht bezwingen können. Und wahrlich, zu unserem Herrn werden wir zurückkehren.",
                "hi": "उसकी महिमा हो जिसने इसे हमारे अधीन कर दिया, और हम इसे अन्यथा वश में नहीं कर सकते थे। और वास्तव में हम अपने रब की ओर लौटने वाले हैं।",
                "tr": "Bunu bizim hizmetimize veren Allah'ı tenzih ederiz, yoksa biz buna güç yetiremezdik. Şüphesiz biz Rabbimize döneceğiz.",
                "ru": "Пречист Тот, Кто подчинил нам это, ведь мы не могли это осилить. И, поистине, к нашему Господу мы вернемся."
            ],
            "O Allah, You are my Lord, there is none worthy of worship but You. You created me and I am Your slave. I keep Your covenant, and my pledge to You so far as I am able.": [
                "ar": "",
                "ur": "اے اللہ! تو میرا رب ہے، تیرے سوا کوئی عبادت کے لائق نہیں۔ تو نے مجھے پیدا کیا اور میں تیرا بندہ ہوں۔ میں اپنی طاقت کے مطابق تیرے عہد اور وعدے پر قائم ہوں۔",
                "fr": "Ô Allah, Tu es mon Seigneur, il n'y a de divinité digne d'adoration que Toi. Tu m'as créé et je suis Ton serviteur. Je respecte Ton alliance et ma promesse envers Toi autant que je le peux.",
                "zh-Hans": "主啊！您是我的主，除您之外绝无应受崇拜的。您创造了我，我是您的奴仆。我尽我所能遵守您的誓约和对您的承诺。",
                "de": "O Allah, Du bist mein Herr, es gibt keinen anbetungswürdigen Gott außer Dir. Du hast mich erschaffen und ich bin Dein Diener. Ich halte mich an Deinen Bund und mein Versprechen an Dich, soweit ich kann.",
                "hi": "हे अल्लाह, आप मेरे भगवान हैं, आपके सिवा कोई पूजा के योग्य नहीं है। आपने मुझे बनाया है और मैं आपका दास हूं। मैं अपनी क्षमता के अनुसार आपके वादे और प्रतिज्ञा का पालन करता हूं।",
                "tr": "Ey Allah'ım! Sen benim Rabbimsin, senden başka ibadete layık ilah yoktur. Beni sen yarattın ve ben senin kulunum. Gücüm yettiğince sana verdiğim söze ve ahde sadığım.",
                "ru": "О Аллах, Ты — мой Господь, нет божества, достойного поклонения, кроме Тебя. Ты создал меня, и я — Твой раб. И я верен Своему завету и обещанию Тебе, насколько это в моих силах."
            ],
            "Our Lord, we have wronged ourselves, and if You do not forgive us and have mercy upon us, we will surely be among the losers.": [
                "ar": "",
                "ur": "اے ہمارے رب! ہم نے اپنی جانوں پر ظلم کیا، اور اگر تو نے ہمیں معاف نہ کیا اور ہم پر رحم نہ فرمایا، تو یقیناً ہم خسارہ پانے والوں میں سے ہو جائیں گے۔",
                "fr": "Notre Seigneur, nous nous sommes fait du tort à nous-mêmes, et si Tu ne nous pardonnes pas et ne nous fais pas miséricorde, nous serons certainement parmi les perdants.",
                "zh-Hans": "我们的主啊！我们亏待了自己，如果您不宽恕我们，不怜悯我们，我们必定会成为失败者。",
                "de": "Unser Herr, wir haben uns selbst Unrecht getan, und wenn Du uns nicht vergibst und Dich unser nicht erbarmst, werden gewiss unter den Verlierern sein.",
                "hi": "हे हमारे रब, हमने अपने आप पर अत्याचार किया है, और यदि आप हमें क्षमा नहीं करते हैं और हम पर दया नहीं करते हैं, तो हम निश्चित रूप से हारने वालों में से होंगे।",
                "tr": "Rabbimiz! Biz kendimize zulmettik, eğer bizi bağışlamaz ve bize acımazsan muhakkak ziyana uğrayanlardan oluruz.",
                "ru": "Господь наш, мы поступили несправедливо по отношению к себе, и если Ты не простишь нас и не помилуешь нас, мы непременно окажемся в числе потерпевших убыток."
            ],
            "O Ever-Living, O Sustainer, in Your Mercy I seek relief. Rectify for me all of my affairs and do not leave me to myself, even for the blink of an eye.": ["ar": "", "ur": "O Ever-Living, O Sustainer, in Your Mercy I seek relief. Rectify for me all of my affairs and do not leave me to myself, even for the blink of an eye.", "fr": "O Ever-Living, O Sustainer, in Your Mercy I seek relief. Rectify for me all of my affairs and do not leave me to myself, even for the blink of an eye.", "zh-Hans": "O Ever-Living, O Sustainer, in Your Mercy I seek relief. Rectify for me all of my affairs and do not leave me to myself, even for the blink of an eye.", "de": "O Ever-Living, O Sustainer, in Your Mercy I seek relief. Rectify for me all of my affairs and do not leave me to myself, even for the blink of an eye.", "hi": "O Ever-Living, O Sustainer, in Your Mercy I seek relief. Rectify for me all of my affairs and do not leave me to myself, even for the blink of an eye.", "tr": "O Ever-Living, O Sustainer, in Your Mercy I seek relief. Rectify for me all of my affairs and do not leave me to myself, even for the blink of an eye.", "ru": "O Ever-Living, O Sustainer, in Your Mercy I seek relief. Rectify for me all of my affairs and do not leave me to myself, even for the blink of an eye."],
            "Sufficient for us is Allah, and [He is] the best Disposer of affairs.": ["ar": "", "ur": "Sufficient for us is Allah, and [He is] the best Disposer of affairs.", "fr": "Sufficient for us is Allah, and [He is] the best Disposer of affairs.", "zh-Hans": "Sufficient for us is Allah, and [He is] the best Disposer of affairs.", "de": "Sufficient for us is Allah, and [He is] the best Disposer of affairs.", "hi": "Sufficient for us is Allah, and [He is] the best Disposer of affairs.", "tr": "Sufficient for us is Allah, and [He is] the best Disposer of affairs.", "ru": "Sufficient for us is Allah, and [He is] the best Disposer of affairs."],
            "Our Lord, give us in this world [that which is] good and in the Hereafter [that which is] good and protect us from the punishment of the Fire.": ["ar": "", "ur": "Our Lord, give us in this world [that which is] good and in the Hereafter [that which is] good and protect us from the punishment of the Fire.", "fr": "Our Lord, give us in this world [that which is] good and in the Hereafter [that which is] good and protect us from the punishment of the Fire.", "zh-Hans": "Our Lord, give us in this world [that which is] good and in the Hereafter [that which is] good and protect us from the punishment of the Fire.", "de": "Our Lord, give us in this world [that which is] good and in the Hereafter [that which is] good and protect us from the punishment of the Fire.", "hi": "Our Lord, give us in this world [that which is] good and in the Hereafter [that which is] good and protect us from the punishment of the Fire.", "tr": "Our Lord, give us in this world [that which is] good and in the Hereafter [that which is] good and protect us from the punishment of the Fire.", "ru": "Our Lord, give us in this world [that which is] good and in the Hereafter [that which is] good and protect us from the punishment of the Fire."],
            "Our Lord, let not our hearts deviate after You have guided us and grant us from Yourself mercy. Indeed, You are the Bestower.": ["ar": "", "ur": "Our Lord, let not our hearts deviate after You have guided us and grant us from Yourself mercy. Indeed, You are the Bestower.", "fr": "Our Lord, let not our hearts deviate after You have guided us and grant us from Yourself mercy. Indeed, You are the Bestower.", "zh-Hans": "Our Lord, let not our hearts deviate after You have guided us and grant us from Yourself mercy. Indeed, You are the Bestower.", "de": "Our Lord, let not our hearts deviate after You have guided us and grant us from Yourself mercy. Indeed, You are the Bestower.", "hi": "Our Lord, let not our hearts deviate after You have guided us and grant us from Yourself mercy. Indeed, You are the Bestower.", "tr": "Our Lord, let not our hearts deviate after You have guided us and grant us from Yourself mercy. Indeed, You are the Bestower.", "ru": "Our Lord, let not our hearts deviate after You have guided us and grant us from Yourself mercy. Indeed, You are the Bestower."],
            "My Lord, have mercy upon them as they brought me up [when I was] small.": ["ar": "", "ur": "My Lord, have mercy upon them as they brought me up [when I was] small.", "fr": "My Lord, have mercy upon them as they brought me up [when I was] small.", "zh-Hans": "My Lord, have mercy upon them as they brought me up [when I was] small.", "de": "My Lord, have mercy upon them as they brought me up [when I was] small.", "hi": "My Lord, have mercy upon them as they brought me up [when I was] small.", "tr": "My Lord, have mercy upon them as they brought me up [when I was] small.", "ru": "My Lord, have mercy upon them as they brought me up [when I was] small."],
            "O Allah, by You we enter the morning and by You we enter the evening, by You we live and by You we die, and to You is the resurrection.": ["ar": "", "ur": "اے اللہ، تیرے ہی ساتھ ہم نے صبح کی اور تیرے ہی ساتھ شام کی، تیرے ہی ساتھ ہم جیتے اور مرتے ہیں، اور تیری ہی طرف اٹھنا ہے۔", "fr": "Ô Allah, par Toi nous entrons dans le matin et par Toi dans le soir, par Toi nous vivons et par Toi nous mourons, et vers Toi est la résurrection.", "zh-Hans": "真主啊，凭你我们进入早晨，凭你我们进入夜晚，凭你我们生，凭你我们死，复活归于你。", "de": "O Allah, durch Dich treten wir in den Morgen und in den Abend, durch Dich leben wir und sterben wir, und zu Dir ist die Auferstehung.", "hi": "ऐ अल्लाह, तेरे ही साथ हम सुबह और शाम करते हैं, तेरे ही साथ जीते और मरते हैं, और तेरी ही ओर पुनरुत्थान है।", "tr": "Allah'ım, senin sayende sabaha ve akşama ulaştık, senin sayende yaşar ve ölürüz; dönüş sanadır.", "ru": "О Аллах, с Тобой мы встречаем утро и вечер, Тобой мы живём и умираем, и к Тебе воскрешение."],
            "In Your name, O Allah, I die and I live.": ["ar": "", "ur": "اے اللہ، تیرے ہی نام کے ساتھ میں مرتا اور جیتا ہوں۔", "fr": "En Ton nom, ô Allah, je meurs et je vis.", "zh-Hans": "真主啊，以你的名义，我死去，我活着。", "de": "In Deinem Namen, o Allah, sterbe ich und lebe ich.", "hi": "ऐ अल्लाह, तेरे ही नाम से मैं मरता और जीता हूँ।", "tr": "Allah'ım, senin adınla ölür ve dirilirim.", "ru": "С именем Твоим, о Аллах, я умираю и живу."],
            "All praise is for Allah who gave us life after having taken it from us, and unto Him is the resurrection.": ["ar": "", "ur": "تمام تعریف اللہ کے لیے ہے جس نے ہمیں موت دینے کے بعد زندہ کیا اور اسی کی طرف اٹھنا ہے۔", "fr": "Louange à Allah qui nous a rendu la vie après nous l'avoir prise, et vers Lui est la résurrection.", "zh-Hans": "一切赞颂归于真主，他使我们死后复生，复活归于他。", "de": "Alles Lob gebührt Allah, der uns das Leben gab, nachdem Er es uns genommen hatte, und zu Ihm ist die Auferstehung.", "hi": "सारी प्रशंसा अल्लाह के लिए है जिसने हमें मृत्यु के बाद जीवन दिया, और उसी की ओर पुनरुत्थान है।", "tr": "Bizi öldürdükten sonra dirilten Allah'a hamd olsun; dönüş O'nadır.", "ru": "Хвала Аллаху, Который оживил нас после того, как умертвил, и к Нему воскрешение."],
            "O Allah, help me to remember You, to thank You, and to worship You well.": ["ar": "", "ur": "اے اللہ، اپنے ذکر، شکر اور بہترین عبادت میں میری مدد فرما۔", "fr": "Ô Allah, aide-moi à T'invoquer, à Te remercier et à T'adorer de la meilleure manière.", "zh-Hans": "真主啊，求你助我记念你、感谢你、好好敬拜你。", "de": "O Allah, hilf mir, Deiner zu gedenken, Dir zu danken und Dich auf beste Weise anzubeten.", "hi": "ऐ अल्लाह, तुझे याद करने, तेरा शुक्र करने और अच्छी तरह तेरी इबादत करने में मेरी मदद कर।", "tr": "Allah'ım, seni anmama, sana şükretmeme ve sana güzelce ibadet etmeme yardım et.", "ru": "О Аллах, помоги мне поминать Тебя, благодарить Тебя и наилучшим образом поклоняться Тебе."],
            "There is no deity except Allah, the Mighty, the Forbearing. There is no deity except Allah, Lord of the Mighty Throne. There is no deity except Allah, Lord of the heavens, Lord of the earth and Lord of the Noble Throne.": ["ar": "", "ur": "اللہ کے سوا کوئی معبود نہیں، جو عظیم اور بردبار ہے۔ اللہ کے سوا کوئی معبود نہیں، جو عرشِ عظیم کا رب ہے۔ اللہ کے سوا کوئی معبود نہیں، جو آسمانوں، زمین اور عرشِ کریم کا رب ہے۔", "fr": "Il n'y a de divinité qu'Allah, le Puissant, le Longanime. Il n'y a de divinité qu'Allah, Seigneur du Trône immense. Il n'y a de divinité qu'Allah, Seigneur des cieux, Seigneur de la terre et Seigneur du Trône noble.", "zh-Hans": "除真主外绝无应受崇拜者，他是伟大的、宽容的。除真主外绝无应受崇拜者，他是伟大宝座之主。除真主外绝无应受崇拜者，他是诸天之主、大地之主、尊贵宝座之主。", "de": "Es gibt keinen Gott außer Allah, dem Gewaltigen, dem Nachsichtigen. Es gibt keinen Gott außer Allah, dem Herrn des gewaltigen Throns. Es gibt keinen Gott außer Allah, dem Herrn der Himmel, dem Herrn der Erde und dem Herrn des edlen Throns.", "hi": "अल्लाह के सिवा कोई पूज्य नहीं, वह महान और सहनशील है। अल्लाह के सिवा कोई पूज्य नहीं, वह महान अर्श का रब है। अल्लाह के सिवा कोई पूज्य नहीं, वह आकाशों, धरती और सम्मानित अर्श का रब है।", "tr": "Azîm ve Halîm olan Allah'tan başka ilah yoktur. Büyük Arş'ın Rabbi olan Allah'tan başka ilah yoktur. Göklerin Rabbi, yerin Rabbi ve şerefli Arş'ın Rabbi olan Allah'tan başka ilah yoktur.", "ru": "Нет божества, кроме Аллаха, Великого, Кроткого. Нет божества, кроме Аллаха, Господа великого Трона. Нет божества, кроме Аллаха, Господа небес, Господа земли и Господа благородного Трона."],
            "O Allah, I hope for Your mercy, so do not leave me to myself even for the blink of an eye, and rectify all my affairs. There is no deity except You.": ["ar": "", "ur": "اے اللہ، میں تیری رحمت کا امیدوار ہوں، مجھے پلک جھپکنے کے برابر بھی میرے نفس کے حوالے نہ کر، اور میرے سارے معاملات درست فرما دے۔ تیرے سوا کوئی معبود نہیں۔", "fr": "Ô Allah, j'espère Ta miséricorde ; ne me laisse pas à moi-même, ne serait-ce qu'un clin d'œil, et arrange toutes mes affaires. Il n'y a de divinité que Toi.", "zh-Hans": "真主啊，我期望你的慈悯，求你不要把我交给我自己，哪怕一瞬间，并求你改善我的一切事务。除你之外绝无应受崇拜者。", "de": "O Allah, ich hoffe auf Deine Barmherzigkeit; überlasse mich nicht mir selbst, nicht einmal für einen Wimpernschlag, und bringe alle meine Angelegenheiten in Ordnung. Es gibt keinen Gott außer Dir.", "hi": "ऐ अल्लाह, मैं तेरी रहमत की आशा रखता हूँ, मुझे पलक झपकने भर के लिए भी मेरे हाल पर न छोड़, और मेरे सभी काम सुधार दे। तेरे सिवा कोई पूज्य नहीं।", "tr": "Allah'ım, rahmetini umuyorum; beni göz açıp kapayıncaya kadar bile nefsime bırakma ve bütün işlerimi düzelt. Senden başka ilah yoktur.", "ru": "О Аллах, я надеюсь на Твою милость, не оставляй меня наедине с собой даже на мгновение и исправь все мои дела. Нет божества, кроме Тебя."],
            "I seek refuge in the perfect words of Allah from the evil of what He has created.": ["ar": "", "ur": "میں اللہ کے کامل کلمات کی پناہ چاہتا ہوں اس کی مخلوق کے شر سے۔", "fr": "Je cherche refuge dans les paroles parfaites d'Allah contre le mal de ce qu'Il a créé.", "zh-Hans": "我以真主完美的言辞求护佑，免遭他所创造之物的伤害。", "de": "Ich suche Zuflucht in den vollkommenen Worten Allahs vor dem Übel dessen, was Er erschaffen hat.", "hi": "मैं अल्लाह के पूर्ण शब्दों की शरण लेता हूँ उसकी सृष्टि की बुराई से।", "tr": "Yarattıklarının şerrinden Allah'ın eksiksiz kelimelerine sığınırım.", "ru": "Прибегаю к совершенным словам Аллаха от зла того, что Он сотворил."],
            "O Allah, I ask You for well-being in this world and the Hereafter.": ["ar": "", "ur": "اے اللہ، میں تجھ سے دنیا اور آخرت میں عافیت مانگتا ہوں۔", "fr": "Ô Allah, je Te demande le bien-être en ce monde et dans l'au-delà.", "zh-Hans": "真主啊，我求你赐我今世与后世的平安。", "de": "O Allah, ich bitte Dich um Wohlergehen im Diesseits und im Jenseits.", "hi": "ऐ अल्लाह, मैं तुझसे दुनिया और आख़िरत में आफ़ियत माँगता हूँ।", "tr": "Allah'ım, senden dünyada ve ahirette afiyet dilerim.", "ru": "О Аллах, я прошу у Тебя благополучия в этом мире и в мире вечном."],
            "O Allah, guide me and keep me on the straight path.": ["ar": "", "ur": "اے اللہ، مجھے ہدایت دے اور سیدھے راستے پر قائم رکھ۔", "fr": "Ô Allah, guide-moi et maintiens-moi sur le droit chemin.", "zh-Hans": "真主啊，求你引导我，使我坚守正道。", "de": "O Allah, leite mich recht und halte mich auf dem geraden Weg.", "hi": "ऐ अल्लाह, मुझे हिदायत दे और सीधे रास्ते पर क़ायम रख।", "tr": "Allah'ım, bana hidayet ver ve beni doğru yolda sabit kıl.", "ru": "О Аллах, наставь меня и удержи на прямом пути."],
            "My Lord, expand for me my breast and ease for me my task.": ["ar": "", "ur": "اے میرے رب، میرا سینہ کھول دے اور میرا کام آسان کر دے۔", "fr": "Seigneur, ouvre-moi ma poitrine et facilite-moi ma tâche.", "zh-Hans": "我的主啊，求你使我的胸襟开阔，使我的事业顺利。", "de": "Mein Herr, weite mir meine Brust und mache mir meine Aufgabe leicht.", "hi": "मेरे रब, मेरा सीना खोल दे और मेरा काम आसान कर दे।", "tr": "Rabbim, göğsümü genişlet ve işimi kolaylaştır.", "ru": "Господи, раскрой мою грудь и облегчи мне моё дело."],
            "O Allah, we ask You on this journey of ours for righteousness and piety, and for deeds that please You.": ["ar": "", "ur": "اے اللہ، ہم اپنے اس سفر میں تجھ سے نیکی، تقویٰ اور وہ عمل مانگتے ہیں جس سے تو راضی ہو۔", "fr": "Ô Allah, nous Te demandons en ce voyage la bonté et la piété, et des œuvres qui Te satisfont.", "zh-Hans": "真主啊，在这次旅途中，我们求你赐予正义与敬畏，以及使你喜悦的善行。", "de": "O Allah, wir bitten Dich auf dieser unserer Reise um Rechtschaffenheit und Gottesfurcht und um Taten, die Dir gefallen.", "hi": "ऐ अल्लाह, हम इस सफ़र में तुझसे नेकी, परहेज़गारी और ऐसे कर्म माँगते हैं जिनसे तू राज़ी हो।", "tr": "Allah'ım, bu yolculuğumuzda senden iyilik, takva ve razı olacağın ameller dileriz.", "ru": "О Аллах, мы просим Тебя в этом нашем пути о благочестии и богобоязненности и о делах, которыми Ты доволен."],
            "In the name of Allah, I place my trust in Allah, and there is no might nor power except with Allah.": ["ar": "", "ur": "اللہ کے نام سے، میں نے اللہ پر بھروسا کیا، اور اللہ کے سوا نہ کوئی طاقت ہے نہ قوت۔", "fr": "Au nom d'Allah, je place ma confiance en Allah, et il n'y a de force ni de puissance qu'en Allah.", "zh-Hans": "奉真主之名，我托靠真主，除真主外无能无力。", "de": "Im Namen Allahs, ich vertraue auf Allah, und es gibt keine Macht und keine Kraft außer bei Allah.", "hi": "अल्लाह के नाम से, मैंने अल्लाह पर भरोसा किया, और अल्लाह के सिवा न कोई शक्ति है न सामर्थ्य।", "tr": "Allah'ın adıyla, Allah'a tevekkül ettim; güç ve kuvvet ancak Allah'tandır.", "ru": "С именем Аллаха, я уповаю на Аллаха, и нет мощи и силы ни у кого, кроме Аллаха."],
            "In the name of Allah at its beginning and at its end. (Said when one forgets to begin with Bismillah.)": ["ar": "", "ur": "اللہ کے نام سے اس کے شروع اور آخر میں۔ (جب کھانے کے شروع میں بسم اللہ بھول جائے)", "fr": "Au nom d'Allah, à son début et à sa fin. (Dit lorsqu'on a oublié de commencer par Bismillah.)", "zh-Hans": "奉真主之名，于其始与其终。（忘记饭前念太斯米时诵念）", "de": "Im Namen Allahs, an seinem Anfang und an seinem Ende. (Wenn man vergessen hat, mit Bismillah zu beginnen.)", "hi": "अल्लाह के नाम से, इसके आरंभ और अंत में। (जब खाने से पहले बिस्मिल्लाह भूल जाए)", "tr": "Başında ve sonunda Allah'ın adıyla. (Yemeğe besmele ile başlamayı unutunca söylenir.)", "ru": "С именем Аллаха в начале его и в конце его. (Произносится, если забыл сказать «Бисмиллях» перед едой.)"],
            "All praise is for Allah who fed me this and provided it for me without any might or power on my part.": ["ar": "", "ur": "تمام تعریف اللہ کے لیے ہے جس نے مجھے یہ کھلایا اور میری کسی طاقت و قوت کے بغیر مجھے عطا کیا۔", "fr": "Louange à Allah qui m'a nourri de ceci et me l'a accordé sans force ni puissance de ma part.", "zh-Hans": "一切赞颂归于真主，他赐我此食，并非凭我的能力与力量。", "de": "Alles Lob gebührt Allah, der mich hiermit gespeist und es mir ohne eigene Macht und Kraft gewährt hat.", "hi": "सारी प्रशंसा अल्लाह के लिए है जिसने मुझे यह खिलाया और मेरी किसी शक्ति और सामर्थ्य के बिना मुझे दिया।", "tr": "Bana bunu yediren ve benden hiçbir güç ve kuvvet olmaksızın onu bana rızık olarak veren Allah'a hamd olsun.", "ru": "Хвала Аллаху, Который накормил меня этим и наделил меня этим без всякой мощи и силы с моей стороны."],
            "My Lord, enable me to be grateful for Your favour which You have bestowed upon me and upon my parents, and to do righteousness of which You approve.": ["ar": "", "ur": "اے میرے رب، مجھے توفیق دے کہ میں تیری اس نعمت کا شکر کروں جو تو نے مجھ پر اور میرے والدین پر کی، اور ایسا نیک عمل کروں جسے تو پسند کرے۔", "fr": "Seigneur, permets-moi de rendre grâce pour Ton bienfait dont Tu m'as comblé ainsi que mes parents, et d'accomplir le bien que Tu agrées.", "zh-Hans": "我的主啊，求你启示我，使我感谢你赐予我和我父母的恩典，并做你所喜悦的善行。", "de": "Mein Herr, gib mir ein, dass ich für Deine Gnade dankbar bin, die Du mir und meinen Eltern erwiesen hast, und dass ich Gutes tue, das Dir wohlgefällt.", "hi": "मेरे रब, मुझे तौफ़ीक़ दे कि मैं तेरी उस नेमत का शुक्र करूँ जो तूने मुझ पर और मेरे माता-पिता पर की, और ऐसा नेक काम करूँ जिससे तू राज़ी हो।", "tr": "Rabbim, bana ve anne babama verdiğin nimete şükretmemi ve razı olacağın salih ameller işlememi bana nasip et.", "ru": "Господи, внуши мне быть благодарным за Твою милость, которую Ты оказал мне и моим родителям, и совершать праведные дела, которыми Ты доволен."],
            "O Allah, benefit me with what You have taught me, teach me what will benefit me, and increase me in knowledge.": ["ar": "", "ur": "اے اللہ، جو تو نے مجھے سکھایا اس سے مجھے نفع دے، مجھے وہ سکھا جو میرے لیے نفع مند ہو، اور میرے علم میں اضافہ فرما۔", "fr": "Ô Allah, fais que ce que Tu m'as enseigné me soit utile, enseigne-moi ce qui me sera utile et accrois mon savoir.", "zh-Hans": "真主啊，求你使我从你所教的知识中受益，教授我有益的知识，并增加我的知识。", "de": "O Allah, lass mir nützen, was Du mich gelehrt hast, lehre mich, was mir nützt, und mehre mein Wissen.", "hi": "ऐ अल्लाह, जो तूने मुझे सिखाया उससे मुझे लाभ दे, मुझे वह सिखा जो मेरे लिए लाभदायक हो, और मेरे ज्ञान में वृद्धि कर।", "tr": "Allah'ım, bana öğrettiklerinle beni faydalandır, bana fayda verecek şeyleri öğret ve ilmimi artır.", "ru": "О Аллах, принеси мне пользу тем, чему Ты меня научил, научи меня тому, что принесёт мне пользу, и приумножь моё знание."],
            "Allah, there is no deity except Him, the Ever-Living, the Sustainer of existence. Neither drowsiness overtakes Him nor sleep. To Him belongs whatever is in the heavens and whatever is on the earth. Who is it that can intercede with Him except by His permission? He knows what is before them and what will be after them, and they encompass not a thing of His knowledge except for what He wills. His Kursi extends over the heavens and the earth, and their preservation tires Him not. And He is the Most High, the Most Great. (Ayat al-Kursi)": ["ar": "", "ur": "اللہ، اس کے سوا کوئی معبود نہیں، وہ زندہ اور قائم رکھنے والا ہے۔ اسے نہ اونگھ آتی ہے نہ نیند۔ جو کچھ آسمانوں اور زمین میں ہے سب اسی کا ہے۔ کون ہے جو اس کی اجازت کے بغیر اس کے پاس سفارش کرے؟ وہ جانتا ہے جو ان کے سامنے ہے اور جو ان کے پیچھے ہے، اور وہ اس کے علم میں سے کسی چیز کا احاطہ نہیں کر سکتے مگر جتنا وہ چاہے۔ اس کی کرسی آسمانوں اور زمین کو گھیرے ہوئے ہے، اور ان کی حفاظت اسے نہیں تھکاتی، اور وہ بلند و عظیم ہے۔ (آیت الکرسی)", "fr": "Allah ! Point de divinité à part Lui, le Vivant, Celui qui subsiste par Lui-même. Ni somnolence ni sommeil ne Le saisissent. À Lui appartient ce qui est dans les cieux et sur la terre. Qui peut intercéder auprès de Lui sans Sa permission ? Il connaît leur passé et leur futur, et de Sa science ils n'embrassent que ce qu'Il veut. Son Trône déborde les cieux et la terre, dont la garde ne Lui coûte aucune peine. Et Il est le Très-Haut, le Très-Grand. (Ayat al-Kursi)", "zh-Hans": "真主，除他外绝无应受崇拜的；他是永生不灭的，是维护万物的；瞌睡不能侵犯他，睡眠不能克服他；天地万物都是他的；不经他的许可，谁能在他那里替人说情呢？他知道他们面前的事和身后的事；除他所启示的外，他们绝不能窥测他的玄妙；他的知觉包罗天地，天地的维持不能使他疲倦。他确是至尊的，确是至大的。（宝座经文）", "de": "Allah, es gibt keinen Gott außer Ihm, dem Lebendigen, dem Beständigen. Ihn überkommt weder Schlummer noch Schlaf. Ihm gehört, was in den Himmeln und was auf der Erde ist. Wer ist es, der bei Ihm Fürsprache einlegen könnte außer mit Seiner Erlaubnis? Er weiß, was vor ihnen und was hinter ihnen liegt, und sie umfassen nichts von Seinem Wissen, außer was Er will. Sein Thron umfasst die Himmel und die Erde, und ihre Bewahrung beschwert Ihn nicht. Er ist der Erhabene, der Allgewaltige. (Ayat al-Kursi)", "hi": "अल्लाह, उसके सिवा कोई पूज्य नहीं, वह जीवित और सबको संभालने वाला है। उसे न ऊँघ आती है न नींद। जो कुछ आकाशों और धरती में है सब उसी का है। कौन है जो उसकी अनुमति के बिना उसके पास सिफ़ारिश करे? वह जानता है जो उनके सामने है और जो उनके पीछे है, और वे उसके ज्ञान में से कुछ भी नहीं समेट सकते सिवाय उसके जो वह चाहे। उसकी कुर्सी आकाशों और धरती को घेरे हुए है, और उनकी रक्षा उसे थकाती नहीं। और वह सर्वोच्च, महान है। (आयतुल कुर्सी)", "tr": "Allah, O'ndan başka ilah yoktur; diridir, her şeyi ayakta tutandır. O'nu ne uyuklama tutar ne de uyku. Göklerde ve yerde ne varsa O'nundur. O'nun izni olmadan katında kim şefaat edebilir? Onların önlerindekini ve arkalarındakini bilir. O'nun dilediği dışında, ilminden hiçbir şeyi kavrayamazlar. Kürsüsü gökleri ve yeri kaplamıştır; onları korumak O'na ağır gelmez. O yücedir, büyüktür. (Âyetü'l-Kürsî)", "ru": "Аллах, нет божества, кроме Него, Живого, Вседержителя. Им не овладевают ни дремота, ни сон. Ему принадлежит то, что на небесах, и то, что на земле. Кто станет заступаться перед Ним без Его дозволения? Он знает их будущее и прошлое, а они постигают из Его знания только то, что Он пожелает. Его Престол объемлет небеса и землю, и не тяготит Его оберегание их. Он Возвышенный, Великий. (Аят аль-Курси)"],
            "Say: He is Allah, the One. Allah, the Eternal Refuge. He neither begets nor is born, nor is there to Him any equivalent. (Surah Al-Ikhlas)": ["ar": "", "ur": "کہو: وہ اللہ ایک ہے۔ اللہ بے نیاز ہے۔ نہ اس نے کسی کو جنا نہ وہ جنا گیا، اور نہ کوئی اس کا ہمسر ہے۔ (سورۃ الاخلاص)", "fr": "Dis : Il est Allah, Unique. Allah, le Seul à être imploré pour ce que nous désirons. Il n'a jamais engendré, n'a pas été engendré non plus, et nul n'est égal à Lui. (Sourate Al-Ikhlas)", "zh-Hans": "你说：他是真主，是独一的主；真主是万物所仰赖的；他没有生产，也没有被生产；没有任何物可以做他的匹敌。（忠诚章）", "de": "Sag: Er ist Allah, ein Einziger. Allah, der Überlegene. Er hat weder gezeugt noch ist Er gezeugt worden, und niemand ist Ihm gleich. (Sure Al-Ichlas)", "hi": "कहो: वह अल्लाह एक है। अल्लाह निरपेक्ष है। न उसने किसी को जन्म दिया, न वह जन्मा, और न कोई उसका समकक्ष है। (सूरह अल-इख़लास)", "tr": "De ki: O Allah birdir. Allah Samed'dir. Doğurmamış ve doğmamıştır. O'nun hiçbir dengi yoktur. (İhlâs Sûresi)", "ru": "Скажи: Он Аллах Единый. Аллах Самодостаточный. Он не родил и не был рождён, и нет никого, равного Ему. (Сура аль-Ихлас)"],
            "Say: I seek refuge in the Lord of daybreak, from the evil of that which He created, and from the evil of darkness when it settles, and from the evil of the blowers in knots, and from the evil of an envier when he envies. (Surah Al-Falaq)": ["ar": "", "ur": "کہو: میں صبح کے رب کی پناہ مانگتا ہوں، اس کی مخلوق کے شر سے، اور اندھیری رات کے شر سے جب وہ چھا جائے، اور گرہوں میں پھونکنے والیوں کے شر سے، اور حاسد کے شر سے جب وہ حسد کرے۔ (سورۃ الفلق)", "fr": "Dis : Je cherche protection auprès du Seigneur de l'aube naissante, contre le mal des êtres qu'Il a créés, contre le mal de l'obscurité quand elle s'approfondit, contre le mal de celles qui soufflent sur les nœuds, et contre le mal de l'envieux quand il envie. (Sourate Al-Falaq)", "zh-Hans": "你说：我求庇于曙光的主，免遭他所创造者的毒害；免遭黑夜笼罩时的毒害；免遭吹破坚结者的毒害；免遭嫉妒者嫉妒时的毒害。（曙光章）", "de": "Sag: Ich nehme Zuflucht beim Herrn des Tagesanbruchs vor dem Übel dessen, was Er erschaffen hat, vor dem Übel der Dunkelheit, wenn sie hereinbricht, vor dem Übel der Knotenanbläserinnen und vor dem Übel eines Neiders, wenn er neidet. (Sure Al-Falaq)", "hi": "कहो: मैं सुबह के रब की शरण लेता हूँ, उसकी सृष्टि की बुराई से, और अंधेरी रात की बुराई से जब वह छा जाए, और गाँठों में फूँकने वालियों की बुराई से, और ईर्ष्या करने वाले की बुराई से जब वह ईर्ष्या करे। (सूरह अल-फ़लक़)", "tr": "De ki: Yarattığı şeylerin şerrinden, karanlığı çöktüğü zaman gecenin şerrinden, düğümlere üfleyenlerin şerrinden ve haset ettiği zaman hasetçinin şerrinden sabahın Rabbine sığınırım. (Felak Sûresi)", "ru": "Скажи: Прибегаю к защите Господа рассвета от зла того, что Он сотворил, от зла мрака, когда он наступает, от зла колдуний, дующих на узлы, и от зла завистника, когда он завидует. (Сура аль-Фаляк)"],
            "Say: I seek refuge in the Lord of mankind, the Sovereign of mankind, the God of mankind, from the evil of the retreating whisperer, who whispers in the breasts of mankind, from among the jinn and mankind. (Surah An-Nas)": ["ar": "", "ur": "کہو: میں لوگوں کے رب، لوگوں کے بادشاہ، لوگوں کے معبود کی پناہ مانگتا ہوں، اس وسوسہ ڈالنے والے کے شر سے جو پیچھے ہٹ جاتا ہے، جو لوگوں کے سینوں میں وسوسہ ڈالتا ہے، جنوں اور انسانوں میں سے۔ (سورۃ الناس)", "fr": "Dis : Je cherche protection auprès du Seigneur des hommes, le Souverain des hommes, Dieu des hommes, contre le mal du mauvais conseiller furtif, qui souffle le mal dans les poitrines des hommes, qu'il soit un djinn ou un être humain. (Sourate An-Nas)", "zh-Hans": "你说：我求庇于世人的主宰，世人的君王，世人的神明，免遭潜伏的教唆者的毒害，他在世人的胸中教唆，他是属于精灵和人类的。（世人章）", "de": "Sag: Ich nehme Zuflucht beim Herrn der Menschen, dem König der Menschen, dem Gott der Menschen, vor dem Übel des Einflüsterers, der entweicht, der in die Brüste der Menschen einflüstert, von den Dschinn und den Menschen. (Sure An-Nas)", "hi": "कहो: मैं लोगों के रब, लोगों के बादशाह, लोगों के पूज्य की शरण लेता हूँ, उस वसवसा डालने वाले की बुराई से जो पीछे हट जाता है, जो लोगों के सीनों में वसवसा डालता है, जिन्नों और इंसानों में से। (सूरह अन-नास)", "tr": "De ki: İnsanların Rabbine, insanların Melikine, insanların İlahına sığınırım; insanların göğüslerine vesvese veren, sinsi vesvesecinin şerrinden; cinlerden ve insanlardan. (Nâs Sûresi)", "ru": "Скажи: Прибегаю к защите Господа людей, Царя людей, Бога людей, от зла искусителя, отступающего при поминании Аллаха, который наущает в груди людей, из джиннов и людей. (Сура ан-Нас)"],
            "We have entered the morning and the whole kingdom belongs to Allah. Praise is to Allah. There is no deity except Allah alone, without partner; His is the dominion and His is the praise, and He is able to do all things. My Lord, I ask You for the good of this day and the good of what follows it, and I seek refuge in You from the evil of this day and the evil of what follows it. My Lord, I seek refuge in You from laziness and the misery of old age. My Lord, I seek refuge in You from punishment in the Fire and punishment in the grave.": ["ar": "", "ur": "ہم نے صبح کی اور ساری بادشاہی اللہ کی ہے۔ تمام تعریف اللہ کے لیے ہے۔ اللہ کے سوا کوئی معبود نہیں، وہ اکیلا ہے، اس کا کوئی شریک نہیں؛ اسی کی بادشاہی ہے اور اسی کے لیے تعریف ہے، اور وہ ہر چیز پر قادر ہے۔ اے میرے رب، میں تجھ سے اس دن کی بھلائی اور اس کے بعد کی بھلائی مانگتا ہوں، اور اس دن کے شر اور اس کے بعد کے شر سے تیری پناہ چاہتا ہوں۔ اے میرے رب، میں سستی اور بڑھاپے کی برائی سے تیری پناہ چاہتا ہوں۔ اے میرے رب، میں آگ کے عذاب اور قبر کے عذاب سے تیری پناہ چاہتا ہوں۔", "fr": "Nous voici au matin et le royaume tout entier appartient à Allah. Louange à Allah. Il n'y a de divinité qu'Allah, Seul, sans associé ; à Lui la royauté, à Lui la louange, et Il est capable de toute chose. Seigneur, je Te demande le bien de ce jour et le bien de ce qui le suit, et je cherche refuge auprès de Toi contre le mal de ce jour et le mal de ce qui le suit. Seigneur, je cherche refuge auprès de Toi contre la paresse et la misère de la vieillesse. Seigneur, je cherche refuge auprès de Toi contre un châtiment dans le Feu et un châtiment dans la tombe.", "zh-Hans": "我们进入了早晨，整个王权归于真主。一切赞颂归于真主。除真主外绝无应受崇拜者，他是独一的，没有伙伴；王权归他，赞颂归他，他对万事全能。我的主啊，我求你赐予今日的福和其后的福，并求你护佑我免遭今日的祸和其后的祸。我的主啊，我求你护佑我免于懒惰和老年的困苦。我的主啊，我求你护佑我免于火狱的刑罚和坟墓的刑罚。", "de": "Wir haben den Morgen erreicht, und das ganze Königreich gehört Allah. Alles Lob gebührt Allah. Es gibt keinen Gott außer Allah allein, ohne Teilhaber; Sein ist die Herrschaft und Sein ist das Lob, und Er hat Macht über alle Dinge. Mein Herr, ich bitte Dich um das Gute dieses Tages und das Gute dessen, was ihm folgt, und ich suche Zuflucht bei Dir vor dem Übel dieses Tages und dem Übel dessen, was ihm folgt. Mein Herr, ich suche Zuflucht bei Dir vor Trägheit und dem Elend des hohen Alters. Mein Herr, ich suche Zuflucht bei Dir vor einer Strafe im Feuer und einer Strafe im Grab.", "hi": "हमने सुबह की और सारा राज्य अल्लाह का है। सारी प्रशंसा अल्लाह के लिए है। अल्लाह के सिवा कोई पूज्य नहीं, वह अकेला है, उसका कोई साझी नहीं; उसी का राज्य है और उसी के लिए प्रशंसा है, और वह हर चीज़ पर सामर्थ्यवान है। मेरे रब, मैं तुझसे इस दिन की भलाई और इसके बाद की भलाई माँगता हूँ, और इस दिन की बुराई और इसके बाद की बुराई से तेरी शरण चाहता हूँ। मेरे रब, मैं आलस्य और बुढ़ापे की दुर्दशा से तेरी शरण चाहता हूँ। मेरे रब, मैं आग की यातना और क़ब्र की यातना से तेरी शरण चाहता हूँ।", "tr": "Sabaha ulaştık, mülk de Allah'ındır. Hamd Allah'a mahsustur. Allah'tan başka ilah yoktur, O tektir, ortağı yoktur; mülk O'nundur, hamd O'nadır ve O her şeye kadirdir. Rabbim, senden bu günün hayrını ve ondan sonrasının hayrını dilerim; bu günün şerrinden ve ondan sonrasının şerrinden sana sığınırım. Rabbim, tembellikten ve yaşlılığın kötülüğünden sana sığınırım. Rabbim, ateşteki azaptan ve kabirdeki azaptan sana sığınırım.", "ru": "Мы встретили утро, и всё владычество принадлежит Аллаху. Хвала Аллаху. Нет божества, кроме Аллаха, Единственного, у Которого нет сотоварища; Ему принадлежит владычество и Ему хвала, и Он над всякой вещью мощен. Господи, я прошу у Тебя блага этого дня и блага того, что после него, и прибегаю к Тебе от зла этого дня и зла того, что после него. Господи, я прибегаю к Тебе от лени и немощи старости. Господи, я прибегаю к Тебе от наказания в Огне и наказания в могиле."],
            "O Allah, You are my Lord, there is no deity except You. You created me and I am Your servant, and I keep Your covenant and my pledge to You as far as I am able. I seek refuge in You from the evil of what I have done. I acknowledge Your favour upon me and I acknowledge my sin, so forgive me, for none forgives sins except You. (Sayyid al-Istighfar)": ["ar": "", "ur": "اے اللہ، تو میرا رب ہے، تیرے سوا کوئی معبود نہیں۔ تو نے مجھے پیدا کیا اور میں تیرا بندہ ہوں، اور میں اپنی طاقت بھر تیرے عہد اور وعدے پر قائم ہوں۔ میں اپنے کیے کے شر سے تیری پناہ چاہتا ہوں۔ میں تیری نعمت کا اقرار کرتا ہوں اور اپنے گناہ کا اعتراف کرتا ہوں، پس مجھے بخش دے، کیونکہ تیرے سوا کوئی گناہ نہیں بخشتا۔ (سید الاستغفار)", "fr": "Ô Allah, Tu es mon Seigneur, il n'y a de divinité que Toi. Tu m'as créé et je suis Ton serviteur ; je me tiens à Ton engagement et à ma promesse envers Toi autant que je le peux. Je cherche refuge auprès de Toi contre le mal que j'ai commis. Je reconnais Ton bienfait envers moi et je reconnais mon péché ; pardonne-moi donc, car nul ne pardonne les péchés sauf Toi. (Sayyid al-Istighfar)", "zh-Hans": "真主啊，你是我的主，除你之外绝无应受崇拜者。你创造了我，我是你的仆人，我尽力恪守对你的盟约与承诺。我求你护佑我免遭我所犯之恶。我承认你对我的恩典，也承认我的罪过，求你饶恕我，因为除你之外无人能饶恕罪过。（求恕之首）", "de": "O Allah, Du bist mein Herr, es gibt keinen Gott außer Dir. Du hast mich erschaffen und ich bin Dein Diener, und ich halte Deinen Bund und mein Versprechen an Dich, so gut ich kann. Ich suche Zuflucht bei Dir vor dem Übel dessen, was ich getan habe. Ich bekenne Deine Gnade mir gegenüber und ich bekenne meine Sünde, so vergib mir, denn niemand vergibt die Sünden außer Dir. (Sayyid al-Istighfar)", "hi": "ऐ अल्लाह, तू मेरा रब है, तेरे सिवा कोई पूज्य नहीं। तूने मुझे पैदा किया और मैं तेरा बंदा हूँ, और मैं अपनी सामर्थ्य भर तेरे वचन और वादे पर क़ायम हूँ। मैं अपने किए की बुराई से तेरी शरण चाहता हूँ। मैं तेरी नेमत को स्वीकार करता हूँ और अपने गुनाह को स्वीकार करता हूँ, तो मुझे माफ़ कर दे, क्योंकि तेरे सिवा कोई गुनाह माफ़ नहीं करता। (सय्यिदुल इस्तिग़फ़ार)", "tr": "Allah'ım, sen benim Rabbimsin, senden başka ilah yoktur. Beni sen yarattın, ben senin kulunum; gücüm yettiğince sana verdiğim söz ve ahid üzereyim. Yaptıklarımın şerrinden sana sığınırım. Üzerimdeki nimetini itiraf eder, günahımı da itiraf ederim; beni bağışla, çünkü günahları senden başkası bağışlamaz. (Seyyidü'l-İstiğfar)", "ru": "О Аллах, Ты мой Господь, нет божества, кроме Тебя. Ты создал меня, и я Твой раб, и я верен завету с Тобой и обещанию Тебе, насколько могу. Прибегаю к Тебе от зла того, что я совершил. Признаю Твою милость ко мне и признаю свой грех, прости же меня, ибо никто не прощает грехи, кроме Тебя. (Сайид аль-истигфар)"],
            "O Allah, I have entered the morning calling You to witness, and the bearers of Your Throne, Your angels and all Your creation, that You are Allah, there is no deity except You alone, without partner, and that Muhammad is Your servant and Messenger.": ["ar": "", "ur": "اے اللہ، میں نے صبح کی اور میں تجھے، تیرے عرش کے اٹھانے والوں، تیرے فرشتوں اور تیری ساری مخلوق کو گواہ بناتا ہوں کہ تو ہی اللہ ہے، تیرے سوا کوئی معبود نہیں، تو اکیلا ہے، تیرا کوئی شریک نہیں، اور محمد تیرے بندے اور رسول ہیں۔", "fr": "Ô Allah, me voici au matin, Te prenant à témoin, ainsi que les porteurs de Ton Trône, Tes anges et toute Ta création, que Tu es Allah, qu'il n'y a de divinité que Toi, Seul, sans associé, et que Muhammad est Ton serviteur et Ton Messager.", "zh-Hans": "真主啊，我进入了早晨，我请你作证，也请你宝座的担负者、你的天使和你的一切创造作证：你是真主，除你之外绝无应受崇拜者，你是独一的，没有伙伴，穆罕默德是你的仆人和使者。", "de": "O Allah, ich habe den Morgen erreicht und rufe Dich zum Zeugen, und die Träger Deines Throns, Deine Engel und Deine gesamte Schöpfung, dass Du Allah bist, es gibt keinen Gott außer Dir allein, ohne Teilhaber, und dass Muhammad Dein Diener und Gesandter ist.", "hi": "ऐ अल्लाह, मैंने सुबह की और मैं तुझे, तेरे अर्श के उठाने वालों, तेरे फ़रिश्तों और तेरी सारी सृष्टि को गवाह बनाता हूँ कि तू ही अल्लाह है, तेरे सिवा कोई पूज्य नहीं, तू अकेला है, तेरा कोई साझी नहीं, और मुहम्मद तेरे बंदे और रसूल हैं।", "tr": "Allah'ım, sabaha ulaştım; seni, Arş'ını taşıyanları, meleklerini ve bütün yaratıklarını şahit tutarım ki sen Allah'sın, senden başka ilah yoktur, tek olan sensin, ortağın yoktur ve Muhammed senin kulun ve elçindir.", "ru": "О Аллах, я встретил утро, призывая в свидетели Тебя, носителей Твоего Трона, Твоих ангелов и всё Твоё творение, что Ты Аллах, нет божества, кроме Тебя Одного, у Которого нет сотоварища, и что Мухаммад Твой раб и посланник."],
            "O Allah, whatever blessing has come to me or to any of Your creation this morning is from You alone, without partner; so to You is all praise and to You is all thanks.": ["ar": "", "ur": "اے اللہ، آج صبح مجھ پر یا تیری مخلوق میں سے کسی پر جو بھی نعمت ہے وہ صرف تیری طرف سے ہے، تیرا کوئی شریک نہیں؛ پس تیرے ہی لیے تعریف اور تیرے ہی لیے شکر ہے۔", "fr": "Ô Allah, tout bienfait qui m'est parvenu ce matin, à moi ou à l'une de Tes créatures, vient de Toi Seul, sans associé ; à Toi la louange et à Toi la gratitude.", "zh-Hans": "真主啊，今晨降临于我或你任何创造物的恩典，都唯独来自你，你没有伙伴；一切赞颂归你，一切感谢归你。", "de": "O Allah, welche Gnade auch immer mir oder einem Deiner Geschöpfe an diesem Morgen zuteilwurde, sie ist von Dir allein, ohne Teilhaber; so gebührt Dir alles Lob und Dir aller Dank.", "hi": "ऐ अल्लाह, आज सुबह मुझ पर या तेरी सृष्टि में से किसी पर जो भी नेमत है वह केवल तेरी ओर से है, तेरा कोई साझी नहीं; तो तेरे ही लिए प्रशंसा और तेरे ही लिए शुक्र है।", "tr": "Allah'ım, bu sabah bana veya yaratıklarından herhangi birine ulaşan her nimet yalnız sendendir, ortağın yoktur; hamd sana, şükür sanadır.", "ru": "О Аллах, всякая милость, что пришла этим утром ко мне или к кому-либо из Твоих созданий, только от Тебя Одного, у Которого нет сотоварища; Тебе хвала и Тебе благодарность."],
            "O Allah, grant my body health. O Allah, grant my hearing health. O Allah, grant my sight health. There is no deity except You.": ["ar": "", "ur": "اے اللہ، میرے بدن کو عافیت دے۔ اے اللہ، میری سماعت کو عافیت دے۔ اے اللہ، میری بینائی کو عافیت دے۔ تیرے سوا کوئی معبود نہیں۔", "fr": "Ô Allah, accorde la santé à mon corps. Ô Allah, accorde la santé à mon ouïe. Ô Allah, accorde la santé à ma vue. Il n'y a de divinité que Toi.", "zh-Hans": "真主啊，求你使我的身体健康。真主啊，求你使我的听觉健康。真主啊，求你使我的视觉健康。除你之外绝无应受崇拜者。", "de": "O Allah, schenke meinem Körper Gesundheit. O Allah, schenke meinem Gehör Gesundheit. O Allah, schenke meinem Augenlicht Gesundheit. Es gibt keinen Gott außer Dir.", "hi": "ऐ अल्लाह, मेरे शरीर को स्वस्थ रख। ऐ अल्लाह, मेरी सुनने की शक्ति को स्वस्थ रख। ऐ अल्लाह, मेरी दृष्टि को स्वस्थ रख। तेरे सिवा कोई पूज्य नहीं।", "tr": "Allah'ım, bedenime afiyet ver. Allah'ım, kulağıma afiyet ver. Allah'ım, gözüme afiyet ver. Senden başka ilah yoktur.", "ru": "О Аллах, даруй здоровье моему телу. О Аллах, даруй здоровье моему слуху. О Аллах, даруй здоровье моему зрению. Нет божества, кроме Тебя."],
            "O Allah, I seek refuge in You from disbelief and poverty, and I seek refuge in You from the punishment of the grave. There is no deity except You.": ["ar": "", "ur": "اے اللہ، میں کفر اور فقر سے تیری پناہ چاہتا ہوں، اور قبر کے عذاب سے تیری پناہ چاہتا ہوں۔ تیرے سوا کوئی معبود نہیں۔", "fr": "Ô Allah, je cherche refuge auprès de Toi contre la mécréance et la pauvreté, et je cherche refuge auprès de Toi contre le châtiment de la tombe. Il n'y a de divinité que Toi.", "zh-Hans": "真主啊，我求你护佑我免于不信和贫穷，求你护佑我免于坟墓的刑罚。除你之外绝无应受崇拜者。", "de": "O Allah, ich suche Zuflucht bei Dir vor Unglauben und Armut, und ich suche Zuflucht bei Dir vor der Strafe des Grabes. Es gibt keinen Gott außer Dir.", "hi": "ऐ अल्लाह, मैं कुफ़्र और ग़रीबी से तेरी शरण चाहता हूँ, और क़ब्र की यातना से तेरी शरण चाहता हूँ। तेरे सिवा कोई पूज्य नहीं।", "tr": "Allah'ım, küfürden ve fakirlikten sana sığınırım; kabir azabından sana sığınırım. Senden başka ilah yoktur.", "ru": "О Аллах, я прибегаю к Тебе от неверия и бедности и прибегаю к Тебе от наказания в могиле. Нет божества, кроме Тебя."],
            "Allah is sufficient for me; there is no deity except Him. In Him I have placed my trust, and He is the Lord of the Mighty Throne.": ["ar": "", "ur": "مجھے اللہ کافی ہے، اس کے سوا کوئی معبود نہیں، اسی پر میں نے بھروسا کیا اور وہ عرشِ عظیم کا رب ہے۔", "fr": "Allah me suffit ; il n'y a de divinité que Lui. En Lui je place ma confiance, et Il est le Seigneur du Trône immense.", "zh-Hans": "真主足以为我，除他之外绝无应受崇拜者。我托靠他，他是伟大宝座之主。", "de": "Allah genügt mir; es gibt keinen Gott außer Ihm. Auf Ihn vertraue ich, und Er ist der Herr des gewaltigen Throns.", "hi": "मुझे अल्लाह काफ़ी है, उसके सिवा कोई पूज्य नहीं। उसी पर मैंने भरोसा किया, और वह महान अर्श का रब है।", "tr": "Allah bana yeter; O'ndan başka ilah yoktur. O'na tevekkül ettim; O büyük Arş'ın Rabbidir.", "ru": "Довольно мне Аллаха, нет божества, кроме Него. На Него я уповаю, и Он Господь великого Трона."],
            "O Allah, I ask You for pardon and well-being in this world and the Hereafter. O Allah, I ask You for pardon and well-being in my religion, my worldly life, my family and my wealth. O Allah, conceal my faults and calm my fears. O Allah, guard me from in front of me and behind me, from my right and my left, and from above me, and I seek refuge in Your greatness from being taken unaware from beneath me.": ["ar": "", "ur": "اے اللہ، میں تجھ سے دنیا اور آخرت میں معافی اور عافیت مانگتا ہوں۔ اے اللہ، میں تجھ سے اپنے دین، دنیا، اہل اور مال میں معافی اور عافیت مانگتا ہوں۔ اے اللہ، میرے عیب چھپا دے اور میرے خوف کو امن میں بدل دے۔ اے اللہ، میری حفاظت فرما میرے آگے سے، پیچھے سے، دائیں سے، بائیں سے اور اوپر سے، اور میں تیری عظمت کی پناہ چاہتا ہوں کہ نیچے سے اچانک ہلاک کر دیا جاؤں۔", "fr": "Ô Allah, je Te demande le pardon et le bien-être en ce monde et dans l'au-delà. Ô Allah, je Te demande le pardon et le bien-être dans ma religion, ma vie d'ici-bas, ma famille et mes biens. Ô Allah, couvre mes défauts et apaise mes craintes. Ô Allah, protège-moi par-devant et par-derrière, à ma droite et à ma gauche, et par-dessus moi ; et je cherche refuge dans Ta grandeur contre le fait d'être surpris par-dessous.", "zh-Hans": "真主啊，我求你赐我今世与后世的宽恕与平安。真主啊，我求你在我的宗教、今世、家人和财产上赐我宽恕与平安。真主啊，求你遮掩我的过失，安抚我的恐惧。真主啊，求你护佑我的前后、左右和上方，我以你的伟大求护佑，免遭来自脚下的突袭。", "de": "O Allah, ich bitte Dich um Vergebung und Wohlergehen im Diesseits und im Jenseits. O Allah, ich bitte Dich um Vergebung und Wohlergehen in meiner Religion, meinem Leben, meiner Familie und meinem Besitz. O Allah, verhülle meine Fehler und besänftige meine Ängste. O Allah, beschütze mich von vorn und von hinten, von rechts und von links und von oben, und ich suche Zuflucht in Deiner Größe davor, von unten überrascht zu werden.", "hi": "ऐ अल्लाह, मैं तुझसे दुनिया और आख़िरत में माफ़ी और आफ़ियत माँगता हूँ। ऐ अल्लाह, मैं तुझसे अपने दीन, दुनिया, परिवार और माल में माफ़ी और आफ़ियत माँगता हूँ। ऐ अल्लाह, मेरे ऐब छिपा दे और मेरे डर को अमन में बदल दे। ऐ अल्लाह, मेरी हिफ़ाज़त कर मेरे आगे से, पीछे से, दाएँ से, बाएँ से और ऊपर से, और मैं तेरी अज़मत की शरण चाहता हूँ कि नीचे से अचानक हलाक कर दिया जाऊँ।", "tr": "Allah'ım, senden dünyada ve ahirette af ve afiyet dilerim. Allah'ım, dinimde, dünyamda, ailemde ve malımda senden af ve afiyet dilerim. Allah'ım, ayıplarımı ört, korkularımı gider. Allah'ım, beni önümden, arkamdan, sağımdan, solumdan ve üstümden koru; altımdan ansızın helak edilmekten senin azametine sığınırım.", "ru": "О Аллах, я прошу у Тебя прощения и благополучия в этом мире и в мире вечном. О Аллах, я прошу у Тебя прощения и благополучия в моей религии, мирской жизни, семье и имуществе. О Аллах, сокрой мои недостатки и успокой мои страхи. О Аллах, охрани меня спереди и сзади, справа и слева и сверху, и я прибегаю к Твоему величию от того, чтобы быть внезапно погубленным снизу."],
            "O Allah, Knower of the unseen and the seen, Creator of the heavens and the earth, Lord and Sovereign of all things, I bear witness that there is no deity except You. I seek refuge in You from the evil of my soul, from the evil of Satan and his call to associate others with You, and from bringing harm upon myself or dragging it upon a Muslim.": ["ar": "", "ur": "اے اللہ، غیب اور ظاہر کے جاننے والے، آسمانوں اور زمین کے پیدا کرنے والے، ہر چیز کے رب اور مالک، میں گواہی دیتا ہوں کہ تیرے سوا کوئی معبود نہیں۔ میں اپنے نفس کے شر سے، شیطان کے شر اور اس کے شرک سے، اور اس سے کہ میں اپنے آپ پر کوئی برائی کروں یا کسی مسلمان تک پہنچاؤں، تیری پناہ چاہتا ہوں۔", "fr": "Ô Allah, Connaisseur de l'invisible et du visible, Créateur des cieux et de la terre, Seigneur et Souverain de toute chose, je témoigne qu'il n'y a de divinité que Toi. Je cherche refuge auprès de Toi contre le mal de mon âme, contre le mal de Satan et de son appel à T'associer, et contre le fait de me nuire à moi-même ou de nuire à un musulman.", "zh-Hans": "真主啊，幽玄与明显的全知者，诸天与大地的创造者，万物的主宰与君王，我作证除你之外绝无应受崇拜者。我求你护佑我免遭自身的恶、恶魔的恶及其以物配主的引诱，免于自害或加害于一位穆斯林。", "de": "O Allah, Kenner des Verborgenen und des Sichtbaren, Schöpfer der Himmel und der Erde, Herr und Herrscher über alle Dinge, ich bezeuge, dass es keinen Gott außer Dir gibt. Ich suche Zuflucht bei Dir vor dem Übel meiner Seele, vor dem Übel Satans und seiner Aufforderung, Dir etwas beizugesellen, und davor, mir selbst Schaden zuzufügen oder ihn einem Muslim zuzufügen.", "hi": "ऐ अल्लाह, अनदेखे और देखे हुए के जानने वाले, आकाशों और धरती के रचयिता, हर चीज़ के रब और मालिक, मैं गवाही देता हूँ कि तेरे सिवा कोई पूज्य नहीं। मैं अपने नफ़्स की बुराई से, शैतान की बुराई और उसके शिर्क से, और इससे कि मैं अपने ऊपर कोई बुराई करूँ या किसी मुसलमान तक पहुँचाऊँ, तेरी शरण चाहता हूँ।", "tr": "Allah'ım, gaybı ve görüneni bilen, göklerin ve yerin yaratıcısı, her şeyin Rabbi ve sahibi; şahitlik ederim ki senden başka ilah yoktur. Nefsimin şerrinden, şeytanın şerrinden ve onun şirke çağırmasından, kendime kötülük etmekten ya da bir Müslümana kötülük bulaştırmaktan sana sığınırım.", "ru": "О Аллах, Знающий сокровенное и явное, Творец небес и земли, Господь и Властелин всякой вещи, я свидетельствую, что нет божества, кроме Тебя. Прибегаю к Тебе от зла моей души, от зла шайтана и его призыва к многобожию, и от того, чтобы причинить зло себе или навлечь его на мусульманина."],
            "We have entered the morning upon the natural religion of Islam, the word of sincerity, the religion of our Prophet Muhammad (peace and blessings be upon him), and the way of our father Ibrahim, who was upright and a Muslim, and was not of those who associate others with Allah.": ["ar": "", "ur": "ہم نے اسلام کی فطرت پر، کلمۂ اخلاص پر، اپنے نبی محمد صلی اللہ علیہ وسلم کے دین پر، اور اپنے باپ ابراہیم کی ملت پر صبح کی، جو یکسو مسلمان تھے اور مشرکوں میں سے نہ تھے۔", "fr": "Nous voici au matin sur la religion naturelle de l'Islam, sur la parole de sincérité, sur la religion de notre Prophète Muhammad (paix et bénédictions sur lui) et sur la voie de notre père Ibrahim, droit et soumis, qui n'était pas du nombre des associateurs.", "zh-Hans": "我们进入了早晨，秉持伊斯兰的天性、忠诚之言、我们先知穆罕默德（愿主福安之）的宗教，以及我们的祖先易卜拉欣的道路，他是正直的顺从者，不属于以物配主者。", "de": "Wir haben den Morgen erreicht in der natürlichen Religion des Islam, im Wort der Aufrichtigkeit, in der Religion unseres Propheten Muhammad (Friede und Segen seien auf ihm) und im Glaubensweg unseres Vaters Ibrahim, der rechtgläubig und gottergeben war und nicht zu denen gehörte, die Allah etwas beigesellen.", "hi": "हमने इस्लाम की फ़ितरत पर, इख़लास के कलिमे पर, अपने नबी मुहम्मद (सल्लल्लाहु अलैहि व सल्लम) के दीन पर, और अपने पिता इब्राहीम की मिल्लत पर सुबह की, जो एकनिष्ठ मुसलमान थे और मुशरिकों में से न थे।", "tr": "İslam fıtratı üzere, ihlas kelimesi üzere, Peygamberimiz Muhammed'in (sallallahu aleyhi ve sellem) dini üzere ve hanif bir Müslüman olan, müşriklerden olmayan babamız İbrahim'in milleti üzere sabaha ulaştık.", "ru": "Мы встретили утро в естественной религии ислама, на слове искренности, в религии нашего Пророка Мухаммада (мир ему и благословение) и в общине нашего отца Ибрахима, который был ханифом и мусульманином и не был из числа многобожников."],
            "Glory be to Allah and praise be to Him.": ["ar": "", "ur": "اللہ پاک ہے اور اسی کے لیے تعریف ہے۔", "fr": "Gloire et louange à Allah.", "zh-Hans": "赞美真主超绝万物，赞颂归于他。", "de": "Gepriesen sei Allah und Ihm gebührt das Lob.", "hi": "अल्लाह पवित्र है और उसी के लिए प्रशंसा है।", "tr": "Allah'ı hamd ile tesbih ederim.", "ru": "Пречист Аллах и хвала Ему."],
            "There is no deity except Allah alone, without partner. His is the dominion and His is the praise, and He is able to do all things.": ["ar": "", "ur": "اللہ کے سوا کوئی معبود نہیں، وہ اکیلا ہے، اس کا کوئی شریک نہیں۔ اسی کی بادشاہی ہے اور اسی کے لیے تعریف ہے، اور وہ ہر چیز پر قادر ہے۔", "fr": "Il n'y a de divinité qu'Allah, Seul, sans associé. À Lui la royauté, à Lui la louange, et Il est capable de toute chose.", "zh-Hans": "除真主外绝无应受崇拜者，他是独一的，没有伙伴。王权归他，赞颂归他，他对万事全能。", "de": "Es gibt keinen Gott außer Allah allein, ohne Teilhaber. Sein ist die Herrschaft und Sein ist das Lob, und Er hat Macht über alle Dinge.", "hi": "अल्लाह के सिवा कोई पूज्य नहीं, वह अकेला है, उसका कोई साझी नहीं। उसी का राज्य है और उसी के लिए प्रशंसा है, और वह हर चीज़ पर सामर्थ्यवान है।", "tr": "Allah'tan başka ilah yoktur, O tektir, ortağı yoktur. Mülk O'nundur, hamd O'nadır ve O her şeye kadirdir.", "ru": "Нет божества, кроме Аллаха Единственного, у Которого нет сотоварища. Ему принадлежит владычество и Ему хвала, и Он над всякой вещью мощен."],
            "Glory be to Allah and praise be to Him, as many times as the number of His creation, as much as pleases Him, as much as the weight of His Throne, and as much as the ink of His words. (Morning)": ["ar": "", "ur": "اللہ پاک ہے اور اسی کے لیے تعریف ہے، اس کی مخلوق کی تعداد کے برابر، اس کی رضا کے برابر، اس کے عرش کے وزن کے برابر اور اس کے کلمات کی سیاہی کے برابر۔ (صبح)", "fr": "Gloire et louange à Allah, autant que le nombre de Ses créatures, autant qu'il Lui plaît, autant que le poids de Son Trône et autant que l'encre de Ses paroles. (Matin)", "zh-Hans": "赞美真主超绝万物，赞颂归于他，其数如他的造物之多，如他所喜悦之量，如他宝座之重，如他言辞之墨。（早晨）", "de": "Gepriesen sei Allah und Ihm gebührt das Lob, so oft wie die Zahl Seiner Schöpfung, so viel wie es Ihm gefällt, so viel wie das Gewicht Seines Throns und so viel wie die Tinte Seiner Worte. (Morgen)", "hi": "अल्लाह पवित्र है और उसी के लिए प्रशंसा है, उसकी सृष्टि की संख्या के बराबर, उसकी प्रसन्नता के बराबर, उसके अर्श के वज़न के बराबर और उसके शब्दों की स्याही के बराबर। (सुबह)", "tr": "Yarattıklarının sayısınca, kendisinin razı olacağı kadar, Arş'ının ağırlığınca ve kelimelerinin mürekkebince Allah'ı hamd ile tesbih ederim. (Sabah)", "ru": "Пречист Аллах и хвала Ему столько раз, сколько Его творений, сколько угодно Ему, сколько весит Его Трон и сколько чернил для Его слов. (Утро)"],
            "O Allah, I ask You for beneficial knowledge, good provision, and accepted deeds. (Morning)": ["ar": "", "ur": "اے اللہ، میں تجھ سے نفع مند علم، پاکیزہ رزق اور مقبول عمل مانگتا ہوں۔ (صبح)", "fr": "Ô Allah, je Te demande une science utile, une subsistance licite et des œuvres agréées. (Matin)", "zh-Hans": "真主啊，我求你赐我有益的知识、佳美的给养和被接受的善功。（早晨）", "de": "O Allah, ich bitte Dich um nützliches Wissen, gute Versorgung und angenommene Taten. (Morgen)", "hi": "ऐ अल्लाह, मैं तुझसे लाभदायक ज्ञान, पवित्र रोज़ी और स्वीकृत कर्म माँगता हूँ। (सुबह)", "tr": "Allah'ım, senden faydalı ilim, temiz rızık ve kabul edilmiş amel dilerim. (Sabah)", "ru": "О Аллах, я прошу у Тебя полезного знания, благого удела и принятых дел. (Утро)"],
            "I seek the forgiveness of Allah and repent to Him.": ["ar": "", "ur": "میں اللہ سے مغفرت مانگتا ہوں اور اس کی طرف توبہ کرتا ہوں۔", "fr": "Je demande pardon à Allah et je me repens auprès de Lui.", "zh-Hans": "我向真主求饶恕，并向他悔罪。", "de": "Ich bitte Allah um Vergebung und wende mich reuig Ihm zu.", "hi": "मैं अल्लाह से क्षमा माँगता हूँ और उसी की ओर तौबा करता हूँ।", "tr": "Allah'tan bağışlanma diler ve O'na tövbe ederim.", "ru": "Прошу прощения у Аллаха и приношу Ему покаяние."],
            "O Allah, send prayers and peace upon our Prophet Muhammad.": ["ar": "", "ur": "اے اللہ، ہمارے نبی محمد پر درود و سلام بھیج۔", "fr": "Ô Allah, accorde prières et paix à notre Prophète Muhammad.", "zh-Hans": "真主啊，求你赐福并赐平安于我们的先知穆罕默德。", "de": "O Allah, sende Segen und Frieden auf unseren Propheten Muhammad.", "hi": "ऐ अल्लाह, हमारे नबी मुहम्मद पर दुरूद और सलाम भेज।", "tr": "Allah'ım, Peygamberimiz Muhammed'e salât ve selam eyle.", "ru": "О Аллах, благослови нашего Пророка Мухаммада и приветствуй его миром."],
            "I seek refuge in the perfect words of Allah from the evil of what He has created. (Evening)": ["ar": "", "ur": "میں اللہ کے کامل کلمات کی پناہ چاہتا ہوں اس کی مخلوق کے شر سے۔ (شام)", "fr": "Je cherche refuge dans les paroles parfaites d'Allah contre le mal de ce qu'Il a créé. (Soir)", "zh-Hans": "我以真主完美的言辞求护佑，免遭他所创造之物的伤害。（傍晚）", "de": "Ich suche Zuflucht in den vollkommenen Worten Allahs vor dem Übel dessen, was Er erschaffen hat. (Abend)", "hi": "मैं अल्लाह के पूर्ण शब्दों की शरण लेता हूँ उसकी सृष्टि की बुराई से। (शाम)", "tr": "Yarattıklarının şerrinden Allah'ın eksiksiz kelimelerine sığınırım. (Akşam)", "ru": "Прибегаю к совершенным словам Аллаха от зла того, что Он сотворил. (Вечер)"],
            "My Lord, increase me in knowledge.": ["ar": "", "ur": "My Lord, increase me in knowledge.", "fr": "My Lord, increase me in knowledge.", "zh-Hans": "My Lord, increase me in knowledge.", "de": "My Lord, increase me in knowledge.", "hi": "My Lord, increase me in knowledge.", "tr": "My Lord, increase me in knowledge.", "ru": "My Lord, increase me in knowledge."],
        ]
}
